{
  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT attr_http_response_status_code code, count(*) n, quantile_cont(duration,0.5)/1e6 p50_ms, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-seat-service' AND span_name='GET' GROUP BY ALL",
          "claim": "Seat's outbound GET client spans have p50 about 3.7ms but p95 about 423ms, with HTTP 200 throughout."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, service_name, span_name, attr_span_kind, count(*) n, quantile_cont(duration,0.95)/1e6 p95ms FROM abnormal_traces WHERE service_name='ts-seat-service' AND span_name IN ('GET','POST') AND attr_span_kind='Client' GROUP BY ALL UNION ALL SELECT 'norm', service_name, span_name, attr_span_kind, count(*), quantile_cont(duration,0.95)/1e6 FROM normal_traces WHERE service_name='ts-seat-service' AND span_name IN ('GET','POST') AND attr_span_kind='Client' GROUP BY ALL",
          "claim": "Only seat's GET client calls are slow; its POST client calls to other services stay at about 4-5ms p95."
        },
        {
          "kind": "trace",
          "sql": "WITH g AS (SELECT 'abn' p, trace_id, span_id, duration FROM abnormal_traces WHERE service_name='ts-seat-service' AND span_name='GET') SELECT g.p, CASE WHEN duration>100000000 THEN 'slow' ELSE 'fast' END speed, (g.span_id IN (SELECT parent_span_id FROM abnormal_traces WHERE service_name='ts-config-service' AND attr_span_kind='Server')) has_config_child, count(*) n, quantile_cont(duration,0.5)/1e6 p50 FROM g GROUP BY ALL",
          "claim": "Slow seat GET calls often have a config server child whose own duration is normal, so the extra time sits outside config's handling."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-seat-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, c.service_name caller, s.service_name callee, s.span_name, count(*) n, quantile_cont(s.duration,0.95)/1e6 p95ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel-plan-service' AND s.service_name='ts-seat-service' AND s.attr_span_kind='Server' GROUP BY ALL UNION ALL SELECT 'norm', c.service_name, s.service_name, s.span_name, count(*), quantile_cont(s.duration,0.95)/1e6 FROM normal_traces s JOIN normal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel-plan-service' AND s.service_name='ts-seat-service' AND s.attr_span_kind='Server' GROUP BY ALL",
          "claim": "Travel-plan's calls to seat's left_tickets rose from about 10ms to about 851ms p95."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, c.service_name caller, s.service_name callee, s.span_name, count(*) n, quantile_cont(s.duration,0.95)/1e6 p95ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-ui-dashboard' AND s.service_name='ts-travel-plan-service' AND s.attr_span_kind='Server' GROUP BY ALL UNION ALL SELECT 'norm', c.service_name, s.service_name, s.span_name, count(*), quantile_cont(s.duration,0.95)/1e6 FROM normal_traces s JOIN normal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-ui-dashboard' AND s.service_name='ts-travel-plan-service' AND s.attr_span_kind='Server' GROUP BY ALL",
          "claim": "Dashboard calls to travel-plan's cheapest endpoint rose from about 113ms to about 4097ms p95."
        }
      ]
    }
  ]
}
